    print('  Reputation influence weights (received from):')
    for g, w in insights['reputation_influence_weights'].items():
        if w > 0.01:
            print(f'    {g}: {w:.4f}')
if 'referral_rates' in insights:
    print('  Referral rates (leads per 1000 subs/day):')
    for g, r in insights['referral_rates'].items():
        if r > 0.001:
            print(f'    {g}: {r:.4f}')
