import novamind_api as nm

# Check the pricing API docs to understand set_model_tiers
print('=== PRICING API ===')
with open('docs/api/pricing.json') as f:
    import json
    docs = json.load(f)
    for item in docs:
        if isinstance(item, dict):
            name = item.get('name', item.get('function', ''))
            if 'model' in str(name).lower() or 'tier' in str(name).lower():
                print(json.dumps(item, indent=2))
        else:
            print(item)

print()

# Check marketing API for lead_promotion
print('=== MARKETING API ===')
with open('docs/api/marketing.json') as f:
    docs = json.load(f)
    for item in docs:
        if isinstance(item, dict):
            name = item.get('name', item.get('function', ''))
            if 'lead' in str(name).lower() or 'promo' in str(name).lower():
                print(json.dumps(item, indent=2))
        else:
            print(item)

